import itertools, random

def solve(nums):
    if len(nums) <= 1:
        return nums[:]
    arr = nums[:]
    n = len(arr)
    i = n - 2
    while i >= 0 and arr[i] >= arr[i + 1]:
        i -= 1
    if i == -1:
        return sorted(arr)
    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1:] = reversed(arr[i + 1:])
    return arr

def brute_next(nums):
    perms = sorted(set(itertools.permutations(nums)))
    idx = perms.index(tuple(nums))
    if idx + 1 < len(perms):
        return list(perms[idx+1])
    else:
        return list(sorted(nums))

for _ in range(1000):
    length = random.randint(0,5)
    nums = [random.randint(0,3) for _ in range(length)]
