def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports +, -, *, / where division truncates toward zero.
    Uses integer arithmetic without converting to float to avoid overflow.
    """
    def trunc_div(a, b):
        # Integer division truncating toward zero
        if b == 0:
            raise ZeroDivisionError('division by zero')
        q = a // b
        # Python's // floors toward -inf; adjust if signs differ and there is a remainder
        if (a ^ b) < 0 and a % b != 0:
            q += 1
        return q

    stack = []
    for tok in tokens:
        if tok in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                res = trunc_div(a, b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

