def solve(grid):
    """Count the number of islands (connected components of 1s) in a binary grid.
    Connectivity is 4-directional (up, down, left, right).
    Handles non‑rectangular grids and empty rows safely.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # bounds check: row exists and column within that row's length
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    islands = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

