    Cells are orthogonally adjacent (up, down, left, right). Empty grid or empty rows return 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Determine max cols, treat missing entries as 0
    max_cols = max((len(row) for row in grid), default=0)
    if max_cols == 0:
        return 0
    visited = [[False] * max_cols for _ in range(rows)]
    def get_cell(r, c):
        # Return value if within row length, else 0
        if c < len(grid[r]):
            return grid[r][c]
        return 0
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < max_cols and not visited[ni][nj] and get_cell(ni, nj) == 1:
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(max_cols):
            if get_cell(i, j) == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

