def solve(tokens):
    """Evaluate an RPN expression given as a list of string tokens.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    """
    def trunc_div(a, b):
        # Python's // floors toward -inf; adjust for truncation toward zero.
        q = a // b
        if (a ^ b) < 0 and a % b != 0:
            q += 1
        return q

    stack = []
    for tok in tokens:
        if tok in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # '/'
                res = trunc_div(a, b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

